import{_ as a,o as e,c as n,a5 as o}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"797win系统垃圾清理及预设文件夹路径下文件清理工具","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["win系统问题"],"标签":["win系统清理工具，释放系统存储空间"]},"headers":[],"relativePath":"md/win系统问题/797win系统垃圾清理及预设文件夹路径下文件清理工具.md","filePath":"md/win系统问题/797win系统垃圾清理及预设文件夹路径下文件清理工具.md"}'),r={name:"md/win系统问题/797win系统垃圾清理及预设文件夹路径下文件清理工具.md"};function _(i,t,p,s,l,w){return e(),n("div",null,[...t[0]||(t[0]=[o('<p>windows系统垃圾清理工具，释放系统存储空间，本程序有多种用法，可以视为系统垃圾清理工具，程序打开后默认状态点击开始删除。也可以是指定路径文件及文件夹清理工具。</p><p>程序使用时，需要以管理员身份权限运行</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250730153320175386080036884.png" alt=""></p><p>程序主要功能是清理win系统缓存及垃圾文件清理</p><p>逻辑是将指定文件夹下所有文件及文件夹进行删除，遇到无法删除或在被占用的文件及文件夹则跳过处理。</p><h3 id="另一种用法" tabindex="-1">另一种用法 <a class="header-anchor" href="#另一种用法" aria-label="Permalink to &quot;另一种用法&quot;">​</a></h3><p>可以将程序默认路径导出到txt文档，然后在txt中添加新的文件路径或文件夹路径，一行一个路径，，然后点击导入路径，将修改后的txt文档导入到程序中，实现批量删除指定文件或指定文件夹下所有内容的任务。</p><h3 id="视频演示说明" tabindex="-1">视频演示说明 <a class="header-anchor" href="#视频演示说明" aria-label="Permalink to &quot;视频演示说明&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1RohAzfEpF/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1RohAzfEpF/</a></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1970.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1970.html</a></p>',11)])])}const d=a(r,[["render",_]]);export{c as __pageData,d as default};
